css_snippet:
/* Prevent all font synthesis for better control and consistent UI */
body {
  font-family: 'MyCustomFont', sans-serif;
  font-synthesis: none;
}

/* Allow synthesis for only bold, prevent italic (less common, but an option) */
h1 {
  font-family: 'AnotherFont', serif;
  font-synthesis: weight;
}

/* Allow synthesis for only italic, prevent bold (also less common) */
em {
  font-family: 'SomeFont', sans-serif;
  font-synthesis: style;
}
